package io.mavsdk.kotlin.plugins.ftp_server

/** Provide files or directories to transfer. */
class FtpServer internal constructor(private val native: FtpServerNative) {
    private var closed = false

    /** Possible results returned for FTP server requests. */
    enum class Result(val value: Int) {
        /** Unknown result */
        UNKNOWN(0),
        /** Request succeeded */
        SUCCESS(1),
        /** Directory does not exist */
        DOES_NOT_EXIST(2),
        /** Operations in progress */
        BUSY(3);

        companion object {
            fun fromValue(value: Int): Result = entries.find { it.value == value } ?: UNKNOWN
        }
    }

    /**
     * Set root directory.
     *
     * This is the directory that can then be accessed by a client. The directory needs to exist
     * when this is called. The permissions are the same as the file permission for the user running
     * the server. The root directory can't be changed while an FTP process is in progress.
     *
     * @param path Absolute path of folder
     * @return The result of the request.
     */
    fun setRootDir(path: String): Result = Result.fromValue(native.setRootDir(path))

    internal fun destroy() {
        if (closed) return
        closed = true
        native.destroy()
    }

    class FtpServerException(val result: Result, message: String) : Exception(message)
}

internal interface FtpServerNative {
    fun setRootDir(path: String): Int

    fun destroy()
}

internal expect fun createFtpServerNative(systemHandle: Long): FtpServerNative
